#include "masscan.h"
#include <ctype.h>

typedef unsigned __int128 ipv6;

/***************************************************************************
 ***************************************************************************/
void
rangelist_add(struct RangeList *list, uint64_t begin, uint64_t end)
{
    if (list->count < MAX_RANGE) {
        list->list[list->count].begin = begin;
        list->list[list->count].end = end;
        list->count++;
    }
}

/***************************************************************************
 ***************************************************************************/
static int
range_cmp(const void *a, const void *b)
{
    const struct Range *ra = (const struct Range *)a;
    const struct Range *rb = (const struct Range *)b;
    if (ra->begin < rb->begin)
        return -1;
    if (ra->begin > rb->begin)
        return 1;
    if (ra->end < rb->end)
        return -1;
    if (ra->end > rb->end)
        return 1;
    return 0;
}

/***************************************************************************
 * Sort the list of ranges, and merge overlapping/adjacent ones.
 ***************************************************************************/
void
rangelist_sort(struct RangeList *list)
{
    unsigned i;
    unsigned new_count = 0;

    if (list->count == 0)
        return;
    qsort(list->list, list->count, sizeof(list->list[0]), range_cmp);

    for (i=0; i<list->count; i++) {
        if (new_count == 0) {
            list->list[new_count++] = list->list[i];
        } else if (list->list[i].begin <= list->list[new_count-1].end + 1) {
            if (list->list[i].end > list->list[new_count-1].end)
                list->list[new_count-1].end = list->list[i].end;
        } else {
            list->list[new_count++] = list->list[i];
        }
    }
    list->count = new_count;
}

uint64_t
rangelist_count(struct RangeList *list)
{
    unsigned i;
    uint64_t result = 0;
    for (i=0; i<list->count; i++)
        result += list->list[i].end - list->list[i].begin + 1;
    return result;
}

/***************************************************************************
 * Convert an IPv4 range into a string. If the range is a power-of-two
 * sized, aligned block, then print it as a CIDR range.
 ***************************************************************************/
int
range_to_string(uint64_t begin, uint64_t end, char *buf, size_t buflen, int is_ipv6)
{
    uint64_t size = end - begin + 1;
    unsigned prefix = 0;
    uint64_t mask;

    if (begin == end) {
        if (is_ipv6)
