        (ip>>24)&0xff, (ip>>16)&0xff, (ip>>8)&0xff, (ip>>0)&0xff);
}

/***************************************************************************
 * IPv6 address printing, using RFC 4291 compression rules.
 ***************************************************************************/
void
ipv6_to_string(ipv6_t ip, char *buf, size_t buflen)
{
    unsigned words[8];
    int i, best_start = -1, best_len = 0, cur_start = -1, cur_len = 0;
    int pos = 0;

    for (i=0; i<8; i++)
        words[i] = (unsigned)((ip >> ((7-i)*16)) & 0xffff);

    for (i=0; i<8; i++) {
        if (words[i] == 0) {
            if (cur_start < 0) {
                cur_start = i;
                cur_len = 1;
            } else
                cur_len++;
            if (cur_len > best_len) {
                best_len = cur_len;
                best_start = cur_start;
            }
        } else {
            cur_start = -1;
            cur_len = 0;
        }
    }
    if (best_len < 2)
        best_start = -1;

    for (i=0; i<8; i++) {
        if (best_start >= 0 && i == best_start) {
            if (pos == 0) {
                buf[pos++] = ':';
            }
            buf[pos++] = ':';
            i += best_len - 1;
            continue;
        }
        pos += snprintf(buf+pos, (size_t)(buflen-pos), "%x", words[i]);
        if (i != 7)
            buf[pos++] = ':';
    }
    buf[pos] = '\0';
}

/***************************************************************************
 * Convert a range into a string, using CIDR notation when possible.
 ***************************************************************************/
static int
ipv4_range_to_string(uint64_t begin, uint64_t end, char *buf, size_t buflen)
{
    uint64_t size = end - begin + 1;
    unsigned prefix;
    uint64_t mask;

    if (begin == end) {
        ipv4_to_string((uint32_t)begin, buf, buflen);
        return 0;
    }
    if (size != 0 && ((size & (size-1)) == 0) && ((begin % size) == 0)) {
        prefix = 32;
        while (((uint64_t)1<<(32-prefix)) < size)
            prefix--;
        mask = size - 1;
        if ((begin & mask) == 0) {
            char addr[32];
            ipv4_to_string((uint32_t)begin, addr, sizeof(addr));
            snprintf(buf, buflen, "%s/%u", addr, prefix);
            return 0;
        }
    }
    {
        char a[32], b[32];
        ipv4_to_string((uint32_t)begin, a, sizeof(a));
        ipv4_to_string((uint32_t)end, b, sizeof(b));
        snprintf(buf, buflen, "%s-%s", a, b);
    }
    return 0;
}

