    }
    return 0;
}

/***************************************************************************
 * IPv4 parser
 ***************************************************************************/
int
parse_ipv4(const char *value, uint32_t *result)
{
    uint32_t x = 0;
    unsigned octet = 0;
    unsigned digits = 0;
    const char *p = value;

    if (value == NULL || !isdigit((unsigned char)value[0]))
        return 0;
    while (*p) {
        if (isdigit((unsigned char)*p)) {
            if (digits >= 3)
                return 0;
            x = x * 10 + (*p - '0');
            digits++;
            if (x > 255)
                return 0;
            p++;
        } else if (*p == '.') {
            if (octet >= 3)
                return 0;
            octet++;
            x = x<<8;
            digits = 0;
            p++;
            if (!isdigit((unsigned char)*p))
                return 0;
        } else {
            return 0;
        }
    }
    if (octet != 3)
        return 0;
    *result = x;
    return 1;
}

/***************************************************************************
 * IPv6 parser
 ***************************************************************************/
static unsigned
hexval(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return 0;
}

int
parse_ipv6(const char *value, ipv6_t *result)
{
    const char *p = value;
    unsigned left[8], right[8];
    unsigned nl = 0, nr = 0;
    int has_dbl = 0;
    ipv6_t addr = 0;
    unsigned i;

    if (value == NULL || value[0] == '\0')
        return 0;
    if (strchr(value, ':') == NULL)
        return 0;

    if (p[0] == ':') {
        if (p[1] != ':')
            return 0;
        has_dbl = 1;
        p += 2;
    }
    while (*p) {
        unsigned g = 0, digits = 0;
        const char *start = p;
        while (isxdigit((unsigned char)*p)) {
            g = (g<<4) | hexval(*p);
            digits++;
            p++;
