            /* embedded IPv4 is not supported by masscan */
            return 0;
        }
        if (has_dbl) {
            if (nr >= 8)
                return 0;
            right[nr++] = g;
        } else {
            if (nl >= 8)
                return 0;
            left[nl++] = g;
        }
        if (*p == ':') {
            p++;
            if (*p == ':') {
                if (has_dbl)
                    return 0;
                has_dbl = 1;
                p++;
                if (*p == '\0')
                    break;
                continue;
            } else if (*p == '\0')
                return 0;
        } else if (*p == '\0') {
            break;
        } else {
            return 0;
        }
    }
    if (!has_dbl) {
        if (nl != 8)
            return 0;
        for (i=0; i<8; i++)
            addr = (addr << 16) | left[i];
    } else {
        if (nl + nr > 8)
            return 0;
        for (i=0; i<nl; i++)
            addr = (addr << 16) | left[i];
        for (i=0; i < (8 - nl - nr); i++)
            addr = (addr << 16);
        for (i=0; i<nr; i++)
            addr = (addr << 16) | right[i];
    }
    *result = addr;
    return 1;
}

