static int
is_terminator(char c)
{
    return c == ',' || c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == ':';
}

int
parse_range_string(struct RangeList *list, struct RangeList6 *list6, const char *value,
                   int is_exclude, int verbose_dash)
{
    const char *p = value;
    int result = 1;

    if (value == NULL)
        return 1;

    for (;;) {
        uint32_t ip4;
        ipv6_t ip6;
        int is_v6 = 0;

        while (*p == ' ' || *p == '\t' || *p == ',' || *p == '\r' || *p == '\n')
            p++;
