                    base = ip6 & ~(((ipv6_t)1<<(128-prefix)) - 1);
                mask = prefix == 0 ? 0 : (((ipv6_t)1<<(128-prefix)) - 1);
                rangelist_add6(list6, base, base | mask);
            } else {
                uint32_t mask, base;
                if (prefix == 0)
                    base = 0;
                else
                    base = ip4 & ~((uint32_t)((1ull<<(32-prefix)) - 1));
                mask = prefix == 0 ? 0xFFFFFFFFu : ((uint32_t)((1ull<<(32-prefix)) - 1));
                rangelist_add(list, base, base | mask);
            }
        } else if (*p == '-') {
            uint32_t ip4b;
            ipv6_t ip6b;
            p++;
            if (is_v6) {
                if (parse_ipv6(p, &ip6b)) {
                    p += ipv6_span(p);
                    rangelist_add6(list6, ip6, ip6b);
                } else {
                    if (is_exclude)
                        fprintf(stderr, "ERROR: bad exclude address/range: %s\n", value);
                    else {
                        if (verbose_dash && value[0] == '-')
                            fprintf(stderr, "[-] _parser_next(): unknown coding failure\n");
                        fprintf(stderr, "ERROR: bad IP address/range: %s\n", value);
                    }
                    result = 0;
                    break;
                }
            } else {
                if (parse_ipv4(p, &ip4b)) {
                    p += strspn_digits(p);
                    rangelist_add(list, ip4, ip4b);
                } else {
                    if (is_exclude)
                        fprintf(stderr, "ERROR: bad exclude address/range: %s\n", value);
                    else {
                        if (verbose_dash && value[0] == '-')
                            fprintf(stderr, "[-] _parser_next(): unknown coding failure\n");
                        fprintf(stderr, "ERROR: bad IP address/range: %s\n", value);
                    }
                    result = 0;
                    break;
                }
            }
        } else {
            if (is_v6)
                rangelist_add6(list6, ip6, ip6);
            else
                rangelist_add(list, ip4, ip4);
        }

        /* Find the next separator */
        if (*p == '\0')
            break;
        if (*p == ':' || !is_terminator(*p)) {
            if (*p != ':' && !is_terminator(*p)) {
                if (is_exclude)
                    fprintf(stderr, "ERROR: bad exclude address/range: %s\n", value);
                else {
                    if (verbose_dash && value[0] == '-')
                        fprintf(stderr, "[-] _parser_next(): unknown coding failure\n");
                    fprintf(stderr, "ERROR: bad IP address/range: %s\n", value);
                }
                result = 0;
                break;
            }
            break;      /* ':' terminates the parse */
        }
    }
    return result;
}

/***************************************************************************
 * Parse a port spec, like "80,8080-8090"
 ***************************************************************************/
int
parse_port_string(struct RangeList *list, const char *value)
{
    const char *p = value;
    int result = 1;

    if (value == NULL)
        return 1;

    for (;;) {
        unsigned port1 = 0, port2 = 0;
        int digits = 0;

        while (*p == ' ' || *p == '\t' || *p == ',' || *p == '\r' || *p == '\n')
            p++;
        if (*p == '\0')
            break;
        if (!isdigit((unsigned char)*p)) {
            p++;
            continue;
        }
        while (isdigit((unsigned char)*p)) {
            port1 = port1 * 10 + (*p - '0');
            digits++;
            p++;
        }
        port2 = port1;
        if (*p == '-') {
            p++;
            digits = 0;
            while (isdigit((unsigned char)*p)) {
                port2 = port2 * 10 + (*p - '0');
                digits++;
                p++;
            }
            if (digits == 0)
                port2 = port1;
        }
        if (port1 > 65535 || port2 > 65535) {
            fprintf(stderr, "[-] FAIL: bad target port: %s\n", value);
            fprintf(stderr, "    Hint: a port is a number [0..65535]\n");
            result = 0;
            break;
        }
        rangelist_add(list, port1, port2);
        if (*p == '\0')
            break;
        if (*p == ':' || (!(*p == ',' || *p == ' ' || *p == '\t')))
            break;
    }
    return result;
}
