static void *(*pcap_lookupdev)(char*);
static void *(*pcap_open_offline)(const char*,char*);
static void (*pcap_close)(void*);

#define WRAP(name,fp,ret,args,args2) \
    ret stub_##name args { if (!pcap_module) { LOG(1, "pcap: %s: failed\n", #name); return 0;} return fp args2; }

static void *pcap_module = NULL;
static int is_initialized = 0;

/***************************************************************************
 ***************************************************************************/
void
pcap_init(void)
{
    static const char *libraries[] = {
        "libpcap.so",
        "libpcap.A.dylib",
        "libpcap.dylib",
        "libpcap.so.1",
        "libpcap.so.0.9.5",
