        fprintf(stderr, "[-] FAIL: failed to load libpcap shared library\n");
        fprintf(stderr, "    [hint]: you must install libpcap or WinPcap\n");
        return;
    }

    /* bind all the functions we might need */
    #define RESOLVE(n) do { \
        if (*(void**)&n = dlsym(pcap_module, #n), *(void**)&n == NULL) \
            LOG(1, "pcap: %s: failed\n", #n); \
    } while (0)
    RESOLVE(pcap_close);
    RESOLVE(pcap_datalink);
    RESOLVE(pcap_dispatch);
    RESOLVE(pcap_findalldevs);
    RESOLVE(pcap_freealldevs);
    RESOLVE(pcap_lib_version);
    RESOLVE(pcap_lookupdev);
    RESOLVE(pcap_major_version);
