    RESOLVE(pcap_next);
    RESOLVE(pcap_setdirection);
    RESOLVE(pcap_datalink_val_to_name);
    RESOLVE(pcap_perror);
    RESOLVE(pcap_geterr);
    RESOLVE(pcap_create);
    RESOLVE(pcap_set_snaplen);
    RESOLVE(pcap_set_promisc);
    RESOLVE(pcap_set_timeout);
    RESOLVE(pcap_set_immediate_mode);
    RESOLVE(pcap_set_buffer_size);
    RESOLVE(pcap_set_rfmon);
    RESOLVE(pcap_can_set_rfmon);
    RESOLVE(pcap_activate);
    #undef RESOLVE
}

int
pcap_is_loaded(void)
{
    return pcap_module != NULL;
}
