#include "masscan.h"
#include <ctype.h>
#include <errno.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>

/***************************************************************************
 * Compare two names, ignoring case, and ignoring '-' and '_'.
 ***************************************************************************/
static int
name_cmp(const char *a, const char *b)
{
    while (*a && *b) {
        int ca = tolower((unsigned char)*a);
        int cb = tolower((unsigned char)*b);
        if (ca == '-' || ca == '_') { a++; continue; }
        if (cb == '-' || cb == '_') { b++; continue; }
        if (ca != cb)
            return ca - cb;
        a++;
        b++;
    }
    while (*a && (*a == '-' || *a == '_'))
        a++;
    while (*b && (*b == '-' || *b == '_'))
        b++;
    return tolower((unsigned char)*a) - tolower((unsigned char)*b);
}

/***************************************************************************
 ***************************************************************************/
static int
is_empty_parameter(const char *value)
{
    if (value == NULL)
        return 1;
    for (; *value; value++)
        if (*value != ' ' && *value != '\t')
            return 0;
    return 1;
}

/***************************************************************************
 ***************************************************************************/
static unsigned
parse_uint(const char *value, int *is_error)
{
    unsigned result = 0;
    const char *p = value;
    if (value == NULL) {
        if (is_error)
            *is_error = 1;
        return 0;
    }
    while (isdigit((unsigned char)*p)) {
        result = result * 10 + (*p - '0');
        p++;
    }
    if (*p != '\0') {
        if (is_error)
            *is_error = 1;
    }
    return result;
}

/***************************************************************************
 ***************************************************************************/
static uint64_t
parse_uint64(const char *value, int *is_error)
{
    uint64_t result = 0;
    const char *p = value;
    if (value == NULL) {
        if (is_error)
            *is_error = 1;
        return 0;
    }
    while (isdigit((unsigned char)*p)) {
        result = result * 10 + (*p - '0');
        p++;
    }
    if (*p != '\0') {
        if (is_error)
            *is_error = 1;
    }
    return result;
}

/***************************************************************************
 * Parse the rate.  Errors are reported as:
 *   CONF: non-digit in rate spec: rate=<rest of string>
 ***************************************************************************/
static double
parse_rate(const char *value)
{
    double rate = 0;
    double frac = 0;
    double scale = 0.1;
    const char *p = value;
    int is_frac = 0;

    if (value == NULL)
        return -1;

    /* Whole part */
    while (isdigit((unsigned char)*p)) {
        rate = rate * 10 + (*p - '0');
        p++;
    }
    if (*p == '.') {
        if (isdigit((unsigned char)p[1])) {
            p++;
            while (isdigit((unsigned char)*p)) {
                frac = frac * 10 + (*p - '0');
                p++;
            }
            /* figure out the scale */
            scale = 0.1;
            {
                const char *q = value;
                int ndigits = 0;
                while (isdigit((unsigned char)*q))
                    q++;
                q++;
                while (isdigit((unsigned char)*q)) {
                    ndigits++;
                    q++;
                }
                while (ndigits > 1) {
                    scale *= 10;
                    ndigits--;
                }
                if (ndigits == 0)
                    scale = 1.0;
                while (scale > 0.0000001)
                    scale /= 10.0;
            }
            frac *= scale;
            rate += frac;
            if (*p != '\0') {
                fprintf(stderr, "CONF: non-digit in rate spec: rate=%s\n", p-1 > value ? p : value);
                return -1;
            }
        } else if (p[1] == '\0') {
            /* trailing decimal point, that's ok */
            p++;
        } else {
            fprintf(stderr, "CONF: non-digit in rate spec: rate=%s\n", value);
            return -1;
        }
    } else if (*p != '\0') {
        fprintf(stderr, "CONF: non-digit in rate spec: rate=%s\n", value);
        return -1;
    }
    return rate;
}

/***************************************************************************
 * MAC address parsing
 ***************************************************************************/
static int
parse_mac(const char *value, unsigned char *mac)
{
    unsigned i = 0;
    const char *p = value;
    if (value == NULL)
        return 0;
    while (*p && i < 6) {
        unsigned val = 0;
        unsigned digits = 0;
        while (isxdigit((unsigned char)*p) && digits < 2) {
            unsigned c = isdigit((unsigned char)*p) ? (*p - '0') :
                         (tolower((unsigned char)*p) - 'a' + 10);
            val = val * 16 + c;
            digits++;
            p++;
        }
        if (digits == 0)
            break;
        mac[i++] = (unsigned char)val;
        if (*p == '-' || *p == ':' || *p == '.')
            p++;
        else if (*p != '\0' && i < 6)
            continue;
        else
            break;
    }
    return i == 6 && *p == '\0';
}

