 ***************************************************************************/
static int
parse_hello_type(const char *value)
{
    if (strcmp(value, "http") == 0)
        return 1;
    if (strcmp(value, "ssl") == 0)
        return 2;
    if (strcmp(value, "none") == 0)
        return 0;
    return -1;
}

/***************************************************************************
 ***************************************************************************/
void
masscan_read_config_file(struct Masscan *masscan, const char *filename)
{
    FILE *fp;
    char line[65536];
    char cwd[1024];

    errno = 0;
    fp = fopen(filename, "rb");
    if (fp == NULL) {
        int err = errno;
        fprintf(stderr, "[-] FAIL: reading configuration file\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(err));
        if (getcwd(cwd, sizeof(cwd))) {
            fprintf(stderr, "[-] cwd = %s\n", cwd);
        } else {
            fprintf(stderr, "[-] cwd = \n");
        }
        return;
    }
    masscan_read_config(masscan, filename);
    fclose(fp);
}

/***************************************************************************
 * Read and process a configuration file
 ***************************************************************************/
int
masscan_read_config(struct Masscan *masscan, const char *filename)
{
    FILE *fp;
    char line[65536];
    int index_dummy = 0;
    char *argv_dummy[3];
    int exit_code = 0;

    fp = fopen(filename, "rb");
    if (fp == NULL) {
        int err = errno;
        char cwd[1024];
        fprintf(stderr, "[-] FAIL: reading configuration file\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(err));
        if (getcwd(cwd, sizeof(cwd)))
            fprintf(stderr, "[-] cwd = %s\n", cwd);
        else
            fprintf(stderr, "[-] cwd = \n");
        return 0;
    }

    while (fgets(line, sizeof(line), fp)) {
        char *name, *value;
        char *p = line;
        size_t len;

        /* trim trailing whitespace */
        len = strlen(line);
        while (len && (line[len-1] == '\n' || line[len-1] == '\r' ||
                       line[len-1] == ' ' || line[len-1] == '\t'))
            line[--len] = '\0';

        /* trim leading whitespace */
        while (*p == ' ' || *p == '\t')
            p++;

        /* skip comments and empty lines */
        if (*p == '\0' || *p == '#')
            continue;

        /* strip trailing comment */
        {
            char *h = strchr(p, '#');
            if (h)
                *h = '\0';
            len = strlen(p);
            while (len && (p[len-1] == ' ' || p[len-1] == '\t'))
                p[--len] = '\0';
        }

        name = p;
        value = strchr(p, '=');
        if (value == NULL) {
            /* Lines without an equals sign are ignored */
            continue;
        }
        *value = '\0';
        value++;
        /* trim the name */
        len = strlen(name);
        while (len && (name[len-1] == ' ' || name[len-1] == '\t'))
            name[--len] = '\0';
        while (*name == ' ' || *name == '\t')
            name++;
        /* trim the value */
        while (*value == ' ' || *value == '\t')
            value++;

        /* process it */
        argv_dummy[0] = "";
        argv_dummy[1] = name;
        argv_dummy[2] = value;
        index_dummy = 0;
        {
            int idx = 1;
            int rc = masscan_parse_parameter(masscan, name, value, &idx, 2, argv_dummy);
            if (rc == -1) {
                exit_code = 1;
                break;
            }
        }
    }
    fclose(fp);
    return exit_code == 0;
}
