/*
 * Command line and configuration file parsing
 */
#include "masscan.h"
#include <ctype.h>
#include <errno.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>

/***************************************************************************
 * Compare two names, ignoring case, and ignoring '-' and '_'.
 ***************************************************************************/
static int
name_cmp(const char *a, const char *b)
{
    while (*a && *b) {
        int ca = tolower((unsigned char)*a);
        int cb = tolower((unsigned char)*b);
        if (ca == '-' || ca == '_') { a++; continue; }
        if (cb == '-' || cb == '_') { b++; continue; }
        if (ca != cb)
            return ca - cb;
        a++;
        b++;
    }
    while (*a && (*a == '-' || *a == '_'))
        a++;
    while (*b && (*b == '-' || *b == '_'))
        b++;
    return tolower((unsigned char)*a) - tolower((unsigned char)*b);
}

/***************************************************************************
 ***************************************************************************/
int
is_empty_parameter_str(const char *value)
{
    if (value == NULL)
        return 1;
    for (; *value; value++)
        if (*value != ' ' && *value != '\t')
            return 0;
    return 1;
}

/***************************************************************************
 ***************************************************************************/
static unsigned
parse_uint(const char *value)
{
    unsigned result = 0;
    const char *p = value;
    if (value == NULL)
        return 0;
    while (isdigit((unsigned char)*p)) {
        result = result * 10 + (*p - '0');
        p++;
    }
    return result;
}

/***************************************************************************
 * Parse the rate, reporting errors in the same way the original does.
 ***************************************************************************/
static double
parse_rate(const char *value)
{
    double rate = 0;
    double frac = 0;
    const char *p = value;
    unsigned frac_digits = 0;

    if (value == NULL)
        return -1;

    if (value[0] == '.') {
        if (value[1] == '\0') {
            return 0;
        } else if (isdigit((unsigned char)value[1])) {
            p = value + 1;
            while (isdigit((unsigned char)*p)) {
                frac = frac * 10 + (*p - '0');
                frac_digits++;
                p++;
            }
            while (frac_digits--)
                frac /= 10.0;
            if (*p != '\0') {
                fprintf(stderr, "CONF: non-digit in rate spec: rate=%s\n", p);
                return -1;
            }
            return frac;
        } else {
            fprintf(stderr, "CONF: non-digit in rate spec: rate=%s\n", value);
            return -1;
        }
    }

    while (isdigit((unsigned char)*p)) {
        rate = rate * 10 + (*p - '0');
        p++;
    }
    if (*p == '\0')
        return rate;
    if (*p == '.') {
        if (p[1] == '\0')
            return rate;
        if (!isdigit((unsigned char)p[1])) {
            fprintf(stderr, "CONF: non-digit in rate spec: rate=%s\n", value);
            return -1;
        }
        p++;
        while (isdigit((unsigned char)*p)) {
            frac = frac * 10 + (*p - '0');
            frac_digits++;
            p++;
        }
        while (frac_digits--)
            frac /= 10.0;
        if (*p != '\0') {
            fprintf(stderr, "CONF: non-digit in rate spec: rate=%s\n", p-1);
            return -1;
        }
        return rate + frac;
    }
    fprintf(stderr, "CONF: non-digit in rate spec: rate=%s\n", value);
    return -1;
}

/***************************************************************************
 * MAC address parsing
 ***************************************************************************/
static int
parse_mac(const char *value, unsigned char *mac)
{
    unsigned i = 0;
    const char *p = value;
    if (value == NULL)
        return 0;
    while (*p && i < 6) {
        unsigned val = 0;
        unsigned digits = 0;
        while (isxdigit((unsigned char)*p) && digits < 2) {
            unsigned c = isdigit((unsigned char)*p) ? (*p - '0') :
                         (tolower((unsigned char)*p) - 'a' + 10);
            val = val * 16 + c;
            digits++;
            p++;
        }
        if (digits == 0)
            break;
        mac[i++] = (unsigned char)val;
        if (*p == '-' || *p == ':' || *p == '.')
            p++;
        else
            break;
    }
    return i == 6 && *p == '\0';
}

/***************************************************************************
 ***************************************************************************/
static const char *valid_output_formats[] = {
    "binary", "xml", "grepable", "list", "json", "ndjson", "unicornscan", NULL
};

static int
parse_output_format(const char *value)
{
    unsigned i;
    for (i=0; valid_output_formats[i]; i++)
        if (strcmp(value, valid_output_formats[i]) == 0)
            return (int)i;
    return -1;
}

static int
parse_output_status(const char *value)
{
    if (strcmp(value, "open") == 0)
        return 1;
    if (strcmp(value, "closed") == 0)
        return 2;
    if (strcmp(value, "all") == 0)
        return 3;
    return -1;
}

/***************************************************************************
 * capture/nocapture types
 ***************************************************************************/
static int
capture_type(const char *value)
{
    static const char *names[] = {
        "servername", "cert", "html", "heartbleed", NULL
    };
    unsigned i;
    for (i=0; names[i]; i++)
        if (name_cmp(value, names[i]) == 0)
            return (int)i;
    return -1;
}

/***************************************************************************
 * Parse a shard specification, like "2/4"
 ***************************************************************************/
static int
parse_shard(struct Masscan *masscan, const char *value, const char *name)
{
    const char *p = value;
    unsigned index = 0, total = 0;

    if (value == NULL) {
        fprintf(stderr, "%s: empty parameter\n", name);
        return 1;
    }
    while (isdigit((unsigned char)*p))
        index = index * 10 + (*p++ - '0');
    if (*p != '/') {
        fprintf(stderr, "FAIL: shard spec is wrong\n");
        fprintf(stderr, "hint   it goes like 1/4 2/4 3/4 4/4\n");
        return 1;
    }
    p++;
    while (isdigit((unsigned char)*p))
        total = total * 10 + (*p++ - '0');
    if (index == 0) {
        fprintf(stderr, "FAIL: shard index can't be zero\n");
        fprintf(stderr, "hint   it goes like 1/4 2/4 3/4 4/4\n");
        return 1;
    }
    if (index > total || total == 0) {
        fprintf(stderr, "FAIL: shard spec is wrong\n");
        fprintf(stderr, "hint   it goes like 1/4 2/4 3/4 4/4\n");
        return 1;
    }
    masscan->shard_index = index;
    masscan->shard_total = total;
    return 0;
}

/***************************************************************************
 * Parse the "rotate" values
 ***************************************************************************/
static int
parse_rotate(const char *value, const char *name, unsigned long long *result)
{
    const char *p = value;
    unsigned long long x = 0;
    if (value == NULL)
        return 1;
    while (isdigit((unsigned char)*p)) {
        x = x * 10 + (*p - '0');
        p++;
    }
    if (*p != '\0') {
        fprintf(stderr, "%s: unknown character\n", name);
        return 1;
    }
    *result = x;
    return 0;
}

/***************************************************************************
 ***************************************************************************/
static void
read_ip_file(struct Masscan *masscan, struct RangeList *list, struct RangeList6 *list6,
             const char *filename, int is_exclude)
{
    FILE *fp;
    char line[65536];
    int count = 0;

    fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "[-] FAIL: parsing IP addresses\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(errno));
        exit(1);
    }
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        size_t len;
        (void)len;
        /* strip comments */
        {
            char *h = strchr(p, '#');
            if (h)
                *h = '\0';
        }
        /* trim */
        while (*p == ' ' || *p == '\t')
            p++;
        {
            size_t l = strlen(p);
            while (l && (p[l-1] == '\n' || p[l-1] == '\r' || p[l-1] == ' ' || p[l-1] == '\t'))
                p[--l] = '\0';
        }
        if (*p == '\0')
            continue;
        count++;
        parse_range_string(list, list6, p, is_exclude, 0);
    }
    fclose(fp);
    if (is_exclude)
        fprintf(stderr, "%s: excluding %u ranges from file\n", filename, list->count + list6->count);
    else {
        char msg[64];
        snprintf(msg, sizeof(msg), "%s: including %u ranges from file", filename, count);
        LOGN(1, "%s\n", msg);
    }
}

/***************************************************************************
 ***************************************************************************/
static void
read_hello_file(struct Masscan *masscan, const char *filename)
{
    FILE *fp;
    char buf[65536];
    size_t n;

    fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "[-] [FAILED] --hello-file\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(errno));
        return;
    }
    n = fread(buf, 1, sizeof(buf)-1, fp);
    buf[n] = '\0';
    fclose(fp);
    if (masscan->hello_string_count < 8) {
        masscan->hello_string[masscan->hello_string_count] = strdup(buf);
        masscan->hello_string_count++;
    }
}

/***************************************************************************
 ***************************************************************************/
static void
set_http_field(struct Masscan *masscan, const char *value)
{
    char *name;
    const char *val;
    const char *p = strchr(value, ':');
    if (p == NULL) {
        fprintf(stderr, "[-] --http-header needs both a name and value\n");
        exit(1);
    }
    name = malloc(p - value + 1);
    memcpy(name, value, p-value);
    name[p-value] = '\0';
    val = p+1;
    (void)masscan;
    (void)name;
    (void)val;
}

/***************************************************************************
 * Handle a single long parameter.
 * Returns 1 if the parameter was recognized, 0 if unknown (which will
 * exit the program).
 ***************************************************************************/
int
masscan_parse_parameter(struct Masscan *masscan, const char *name, const char *value)
{
    int x;

    if (value == NULL) {
        fprintf(stderr, "%s: empty parameter\n", name);
        return 1;
    }

    /* ---- target selection ---- */
    if (name_cmp(name, "ports") == 0 || name_cmp(name, "port") == 0) {
        parse_port_string(&masscan->ports, value);
        masscan->is_configured = 1;
        return 0;
    }
    if (name_cmp(name, "range") == 0 || name_cmp(name, "ranges") == 0) {
        parse_range_string(&masscan->targets, &masscan->targets6, value, 0, 1);
        masscan->is_configured = 1;
        return 0;
    }
    if (name_cmp(name, "target") == 0 || name_cmp(name, "targets") == 0) {
        parse_range_string(&masscan->targets, &masscan->targets6, value, 0, 1);
        masscan->is_configured = 1;
        return 0;
    }
    if (name_cmp(name, "exclude") == 0 || name_cmp(name, "excludes") == 0) {
        parse_range_string(&masscan->excludes, &masscan->excludes6, value, 1, 0);
        masscan->is_configured = 1;
        return 0;
    }
    if (name_cmp(name, "excludefile") == 0 || name_cmp(name, "exclude-file") == 0 ||
        name_cmp(name, "blacklist") == 0) {
        read_ip_file(masscan, &masscan->excludes, &masscan->excludes6, value, 1);
        masscan->is_configured = 1;
        return 0;
    }
    if (name_cmp(name, "include-file") == 0 || name_cmp(name, "includefile") == 0) {
        read_ip_file(masscan, &masscan->targets, &masscan->targets6, value, 0);
        masscan->is_configured = 1;
        return 0;
    }

    /* ---- adapter ---- */
    if (name_cmp(name, "adapter-ip") == 0) {
        if (!parse_range_string(&masscan->adapter_ips, NULL, value, 0, 0)) {
            fprintf(stderr, "FAIL: bad source IP address: %s=%s\n", name, value);
            fprintf(stderr, "hint   addresses look like \"192.168.1.23\" or \"2001:db8:1::1ce9\".\n");
            exit(1);
        }
        return 0;
    }
    if (name_cmp(name, "source-ip") == 0) {
        if (!parse_range_string(&masscan->source_ips, NULL, value, 0, 0)) {
            fprintf(stderr, "FAIL: bad source IP address: %s=%s\n", name, value);
            fprintf(stderr, "hint   addresses look like \"192.168.1.23\" or \"2001:db8:1::1ce9\".\n");
            exit(1);
        }
        return 0;
    }
    if (name_cmp(name, "adapter-mac") == 0) {
        unsigned char mac[6];
        if (!parse_mac(value, mac)) {
            fprintf(stderr, "[-] CONF: bad MAC address: %s = %s\n", name, value);
            return 0;
        }
        memcpy(masscan->adapter_mac, mac, 6);
        masscan->has_adapter_mac = 1;
        return 0;
    }
    if (name_cmp(name, "router-mac") == 0) {
        unsigned char mac[6];
        if (!parse_mac(value, mac)) {
            fprintf(stderr, "[-] CONF: bad MAC address: %s = %s\n", name, value);
            return 0;
        }
        memcpy(masscan->router_mac_v4, mac, 6);
        memcpy(masscan->router_mac_v6, mac, 6);
        masscan->has_router_mac_v4 = 1;
        masscan->has_router_mac_v6 = 1;
        return 0;
    }
    if (name_cmp(name, "router-mac-ipv4") == 0) {
        unsigned char mac[6];
        if (!parse_mac(value, mac)) {
            fprintf(stderr, "[-] CONF: bad MAC address: %s = %s\n", name, value);
            return 0;
        }
        memcpy(masscan->router_mac_v4, mac, 6);
        masscan->has_router_mac_v4 = 1;
        return 0;
    }
    if (name_cmp(name, "router-mac-ipv6") == 0) {
        unsigned char mac[6];
        if (!parse_mac(value, mac)) {
            fprintf(stderr, "[-] CONF: bad MAC address: %s = %s\n", name, value);
            return 0;
        }
        memcpy(masscan->router_mac_v6, mac, 6);
        masscan->has_router_mac_v6 = 1;
        return 0;
    }
    if (name_cmp(name, "interface") == 0) {
        masscan->ifname = strdup(value);
        return 0;
    }
    if (name_cmp(name, "adapter-port") == 0 || name_cmp(name, "source-port") == 0) {
        struct RangeList tmp;
        unsigned count_before;
        tmp.count = 0;
        count_before = 0;
        parse_port_string(&tmp, value);
        if (tmp.count != 1) {
            fprintf(stderr, "FAIL: only one '%s' range may be specified, found %u ranges\n",
                    name_cmp(name, "adapter-port") == 0 ? "adapter-port" : "source-port",
                    tmp.count);
            exit(1);
        }
        {
            struct Range r = tmp.list[0];
            uint64_t size = r.end - r.begin + 1;
            if ((size & (size-1)) != 0 || ((r.begin % size) != 0)) {
                fprintf(stderr, "FAIL: source port range must be even power of two: %s=%s\n", name, value);
                exit(1);
            }
        }
        if (name_cmp(name, "adapter-port") == 0)
            masscan->adapter_ports = tmp;
        else
            masscan->adapter_ports = tmp;
        return 0;
    }

    /* ---- timing ---- */
    if (name_cmp(name, "rate") == 0 || name_cmp(name, "max-rate") == 0) {
        double rate = parse_rate(value);
        if (rate >= 0)
            masscan->max_rate = rate;
        return 0;
    }
    if (name_cmp(name, "seed") == 0) {
        masscan->seed = parse_uint64(value);
        masscan->is_seed_set = 1;
        return 0;
    }
    if (name_cmp(name, "shard") == 0 || name_cmp(name, "shards") == 0) {
        parse_shard(masscan, value, name);
        return 0;
    }
    if (name_cmp(name, "retries") == 0 || name_cmp(name, "retry") == 0) {
        masscan->retries = parse_uint(value);
        masscan->has_retries = 1;
        return 0;
    }
    if (name_cmp(name, "wait") == 0) {
        masscan->wait = parse_uint(value);
        masscan->has_wait = 1;
        return 0;
    }
    if (name_cmp(name, "connection-timeout") == 0) {
        masscan->connection_timeout = parse_uint(value);
        masscan->has_connection_timeout = 1;
        return 0;
    }
    if (name_cmp(name, "ttl") == 0) {
        unsigned ttl = parse_uint(value);
        if (ttl >= 256)
            fprintf(stderr, "error: ttl=<n>: expected number less than 256\n");
        else {
            masscan->ttl = ttl;
            masscan->has_ttl = 1;
        }
        return 0;
    }

    /* ---- output ---- */
    if (name_cmp(name, "output-format") == 0) {
        x = parse_output_format(value);
        if (x < 0) {
            fprintf(stderr, "FAIL: unknown output-format: %s\n", value);
            fprintf(stderr, "  hint: 'binary', 'xml', 'grepable', ...\n");
            exit(1);
        }
        masscan->output_format = x;
        return 0;
    }
    if (name_cmp(name, "output-filename") == 0 || name_cmp(name, "output-file") == 0) {
        masscan->output_filename = strdup(value);
        if (masscan->output_format == Output_Default)
            masscan->output_format = Output_XML;
        return 0;
    }
    if (name_cmp(name, "output-status") == 0 || name_cmp(name, "output-show") == 0) {
        x = parse_output_status(value);
        if (x < 0) {
            fprintf(stderr, "FAIL: unknown 'show' spec: %s\n", value);
            exit(1);
        }
        masscan->output_status = x;
        return 0;
    }
    if (name_cmp(name, "append-output") == 0) {
        masscan->is_output_append = 1;
        return 0;
    }
    if (name_cmp(name, "rotate-offset") == 0 || name_cmp(name, "rotate") == 0) {
        unsigned long long v = 0;
        if (parse_rotate(value, "--rotate-offset", &v))
            exit(1);
        masscan->rotate_offset = v;
        return 0;
    }
    if (name_cmp(name, "rotate-size") == 0) {
        unsigned long long v = 0;
        if (parse_rotate(value, "--rotate-size", &v))
            exit(1);
        masscan->rotate_offset = v;
        masscan->has_rotate_size = 1;
        return 0;
    }
    if (name_cmp(name, "rotate-dir") == 0) {
        masscan->rotate_dir = strdup(value);
        return 0;
    }
    if (name_cmp(name, "pcap-filename") == 0 || name_cmp(name, "pcap") == 0) {
        masscan->pcap_filename = strdup(value);
        return 0;
    }

    /* ---- features ---- */
    if (name_cmp(name, "banners") == 0 || name_cmp(name, "banner") == 0) {
        masscan->is_banners = 1;
        return 0;
    }
    if (name_cmp(name, "no-banners") == 0 || name_cmp(name, "no-banner") == 0) {
        masscan->is_banners = 0;
        return 0;
    }
    if (name_cmp(name, "open") == 0) {
        masscan->is_open_only = 1;
        return 0;
    }
    if (name_cmp(name, "packet-trace") == 0) {
        masscan->is_packet_trace = 1;
        return 0;
    }
    if (name_cmp(name, "offline") == 0 || name_cmp(name, "off-line") == 0) {
        masscan->is_offline = 1;
        return 0;
    }
    if (name_cmp(name, "randomize-hosts") == 0) {
        masscan->is_randomize_hosts = 1;
        return 0;
    }
    if (name_cmp(name, "reason") == 0) {
        return 0;
    }
    if (name_cmp(name, "heartbleed") == 0) {
        masscan->is_banners = 1;
        masscan->is_nocapture_cert = 1;
        return 0;
    }
    if (name_cmp(name, "nocapture") == 0 || name_cmp(name, "no-capture") == 0) {
        x = capture_type(value);
        if (x < 0) {
            fprintf(stderr, "FAIL: %s: unknown nocapture type\n", value);
            exit(1);
        }
        if (x == 0) masscan->is_nocapture_servername = 1;
        if (x == 1) masscan->is_nocapture_cert = 1;
        if (x == 2) masscan->is_capture_html = 0;
        if (x == 3) masscan->is_capture_heartbleed = 0;
        return 0;
    }
    if (name_cmp(name, "capture") == 0) {
        x = capture_type(value);
        if (x < 0) {
            fprintf(stderr, "FAIL: %s: unknown capture type\n", value);
            exit(1);
        }
        if (x == 0) masscan->is_nocapture_servername = 0;
        if (x == 1) masscan->is_nocapture_cert = 0;
        if (x == 2) masscan->is_capture_html = 1;
        if (x == 3) masscan->is_capture_heartbleed = 1;
        return 0;
    }
    if (name_cmp(name, "wait") == 0) {
        return 0;
    }
    if (name_cmp(name, "hello") == 0) {
        x = capture_type(value);
        (void)x;
        fprintf(stderr, "FAIL: %s: unknown hello type\n", value);
        exit(1);
    }
    if (name_cmp(name, "hello-string") == 0) {
        if (masscan->hello_string_count < 8)
            masscan->hello_string[masscan->hello_string_count++] = strdup(value);
        return 0;
    }
    if (name_cmp(name, "hello-file") == 0) {
        read_hello_file(masscan, value);
        return 0;
    }
    if (name_cmp(name, "nmap-payload") == 0) {
        read_hello_file(masscan, value);
        return 0;
    }
    if (name_cmp(name, "http-method") == 0) { masscan->http_method = strdup(value); return 0; }
    if (name_cmp(name, "http-version") == 0) { masscan->http_version = strdup(value); return 0; }
    if (name_cmp(name, "http-url") == 0) { masscan->http_url = strdup(value); return 0; }
    if (name_cmp(name, "http-user-agent") == 0) { masscan->http_user_agent = strdup(value); return 0; }
    if (name_cmp(name, "http-host") == 0) { masscan->http_host = strdup(value); return 0; }
    if (name_cmp(name, "http-payload") == 0) { masscan->http_payload = strdup(value); return 0; }
    if (name_cmp(name, "http-field") == 0) { set_http_field(masscan, value); return 0; }
    if (name_cmp(name, "script") == 0) {
        /* requires the Lua library, which we don't have */
        fprintf(stderr, "[-] liblua: failed to load Lua shared library\n");
        fprintf(stderr, "    HINT: you must install Lua library\n");
        abort();
    }
    if (name_cmp(name, "resume") == 0) {
        masscan_read_config(masscan, value);
        return 0;
    }

    /* ---- commands ---- */
    if (name_cmp(name, "echo") == 0) { masscan->is_echo = 1; return 0; }
    if (name_cmp(name, "selftest") == 0 || name_cmp(name, "regress") == 0) {
        masscan->is_selftest = 1;
        return 0;
    }
    if (name_cmp(name, "iflist") == 0 || name_cmp(name, "list-interfaces") == 0) {
        masscan->is_iflist = 1;
        return 0;
    }
    if (name_cmp(name, "interactive") == 0) { masscan->is_interactive = 1; return 0; }
    if (name_cmp(name, "nointeractive") == 0) { masscan->is_interactive = 0; return 0; }
    if (name_cmp(name, "readscan") == 0) {
        masscan->is_readscan = 1;
        masscan->readscan_filename = strdup(value);
        return 0;
    }
    if (name_cmp(name, "debug") == 0) { return 0; }
    if (name_cmp(name, "send-eth") == 0) {
        fprintf(stderr, "nmap(send-eth): unnecessary, we always do --send-eth\n");
        return 0;
    }
    if (name_cmp(name, "send-ip") == 0) {
        fprintf(stderr, "nmap(send-ip): unsupported, we only do --send-eth\n");
        exit(1);
    }
    if (name_cmp(name, "config") == 0 || name_cmp(name, "conf") == 0) {
        masscan_read_config(masscan, value);
        return 0;
    }
    if (name_cmp(name, "version") == 0) { version(); exit(1); }
    if (name_cmp(name, "nmap") == 0) { masscan_nmap_usage(); exit(1); }

    /* unknown parameter */
    fprintf(stderr, "CONF: unknown config option: %s=%s\n", name, value);
    exit(1);
}
