/***************************************************************************
 ***************************************************************************/
int
main(int argc, char *argv[])
{
    struct Masscan masscan[1];
    int i;
    unsigned long long seed;

    install_crash_handler();

    memset(masscan, 0, sizeof(*masscan));
    masscan->is_randomize_hosts = 1;
    masscan->is_nocapture_servername = 1;
    masscan->max_rate = 100;
    masscan->shard_index = 1;
    masscan->shard_total = 1;

    srand((unsigned)time(NULL));
    seed = ((unsigned long long)time(NULL) << 20) ^ (unsigned long long)clock()
            ^ ((unsigned long long)getpid() << 8);
    masscan->seed = seed;

    /*
     * Parse the command line
     */
    if (argc == 1) {
        /* No parameters at all */
        masscan->is_configured = 0;
    }
    for (i=1; i<argc; i++) {
        const char *arg = argv[i];

        if (arg[0] == '-' && arg[1] == '-') {
            /* long option */
            const char *name = arg + 2;
            char namebuf[512];
            const char *value = NULL;
            char *eq = strchr(name, '=');
            if (eq) {
                size_t n = (size_t)(eq - name);
                if (n >= sizeof(namebuf))
                    n = sizeof(namebuf)-1;
                memcpy(namebuf, name, n);
                namebuf[n] = '\0';
                name = namebuf;
                value = eq + 1;
            } else if (i+1 < argc) {
                value = argv[++i];
            } else {
                value = NULL;
            }
            masscan_parse_parameter(masscan, name, value);
            continue;
        }
        if (arg[0] == '-' && arg[1] != '\0') {
            /* short option */
            char c = arg[1];
            const char *value = NULL;
            if (arg[2] != '\0')
                value = arg + 2;
            else if (i+1 < argc)
                value = argv[++i];
            switch (c) {
            case 'h':
                masscan_usage();
                exit(1);
            case 'V':
                version();
                exit(1);
            case 'v':
                verbosity++;
                if (arg[2] != '\0' && isdigit((unsigned char)arg[2]))
                    verbosity = (unsigned)(arg[2] - '0');
                break;
            case 'd':
                verbosity++;
                if (arg[2] != '\0' && isdigit((unsigned char)arg[2]))
                    verbosity = (unsigned)(arg[2] - '0');
                break;
            case 'p':
                if (value == NULL) {
                    fprintf(stderr, "(null): empty parameter\n");
                } else {
                    parse_port_string(&masscan->ports, value);
                    masscan->is_configured = 1;
                }
                break;
            case 'S':
                if (value == NULL) {
                    /* The original program crashes in this case */
                    *(volatile int *)0 = 0;
                } else {
                    if (!parse_range_string(&masscan->source_ips, NULL, value, 0, 0)) {
                        fprintf(stderr, "FAIL: bad source IP address: source-ip=%s\n", value);
                        fprintf(stderr, "hint   addresses look like \"192.168.1.23\" or \"2001:db8:1::1ce9\".\n");
                        exit(1);
                    }
                }
                break;
            case 'g':
                if (value == NULL) {
                    *(volatile int *)0 = 0;
                } else {
                    struct RangeList tmp;
                    tmp.count = 0;
                    parse_port_string(&tmp, value);
                    if (tmp.count != 1) {
                        fprintf(stderr, "FAIL: only one 'source-port' range may be specified, found %u ranges\n", tmp.count);
                        exit(1);
                    }
                    masscan->adapter_ports = tmp;
                }
                break;
            case 'e':
                masscan->ifname = value ? strdup(value) : NULL;
                break;
            case 'c':
                if (value == NULL)
                    masscan_read_config(masscan, NULL);
                else
                    masscan_read_config(masscan, value);
                break;
            case 'i':
                if (arg[2] == 'L' && arg[3] == '\0') {
                    if (value == NULL) {
                        fprintf(stderr, "[-] missing filename for ranges\n");
                        exit(1);
                    }
                    read_ip_file(masscan, &masscan->targets, &masscan->targets6, value, 0);
                    masscan->is_configured = 1;
                } else {
                    masscan->ifname = arg+2;
                }
                break;
            case 'o':
                if (arg[2] == '\0') {
                    fprintf(stderr, "nmap(-o): unknown output format\n");
                    exit(1);
                }
                {
                    int fmt = -1;
                    switch (arg[2]) {
                    case 'L': fmt = Output_List; break;
                    case 'B': fmt = Output_Binary; break;
                    case 'X': fmt = Output_XML; break;
                    case 'J': fmt = Output_JSON; break;
                    case 'D': fmt = Output_NDJSON; break;
                    case 'G': fmt = Output_Grepable; break;
                    case 'U': fmt = Output_Unicornscan; break;
                    case 'A':
                        fprintf(stderr, "nmap(-oA): unsupported output format\n");
                        exit(1);
                    default:
                        fprintf(stderr, "nmap(-o%c): unknown output format\n", arg[2]);
                        exit(1);
                    }
                    masscan->output_format = fmt;
                    if (value == NULL) {
                        fprintf(stderr, "missing output filename\n");
                        exit(1);
                    }
                    masscan->output_filename = strdup(value);
                }
                break;
            case 's':
                if (arg[2] == '\0') {
                    fprintf(stderr, "-s: unknown parameter\n");
                    exit(1);
                }
                switch (arg[2]) {
                case 'S':
                    break;
                case 'T':
                    fprintf(stderr, "nmap(-sT): connect() is too synchronous for cool kids\n");
                    fprintf(stderr, "WARNING: doing SYN scan (-sS) anyway, ignoring (-sT)\n");
                    break;
                case 'U':
                    break;
                case 'P':
                    fprintf(stderr, "nmap(-sP): unsupported option\n");
                    exit(1);
                case 'N':
                    fprintf(stderr, "nmap(-sN): NULL scan not yet supported\n");
                    exit(1);
                case 'X':
                    fprintf(stderr, "nmap(-sX): Xmas scan not yet supported\n");
                    exit(1);
                default:
                    fprintf(stderr, "nmap(-s%c): unsupported option\n", arg[2]);
                    exit(1);
                }
                break;
            case 'T':
                fprintf(stderr, "nmap(-T%c): unsupported, we do timing WAY different than nmap\n", arg[2]);
                exit(1);
            case 'b':
                fprintf(stderr, "nmap(-b): FTP bounce scans will never be supported\n");
                exit(1);
            case 'f':
                fprintf(stderr, "nmap(-f): fragmentation not yet supported\n");
                exit(1);
            case 'A':
                fprintf(stderr, "nmap(-A): unsupported: this tool only does SYN scan\n");
                exit(1);
            case 'F':
                fprintf(stderr, "nmap(-F): unsupported, no slow/fast mode\n");
                exit(1);
            case 'O':
                fprintf(stderr, "nmap(-O): unsupported, OS detection is too complex\n");
                exit(1);
            case 'P':
                fprintf(stderr, "nmap(-P): unsupported option, maybe in future\n");
                exit(1);
            case 'R':
                fprintf(stderr, "nmap(-R): unsupported. This code will never do DNS lookups.\n");
                exit(1);
            case 'r':
                fprintf(stderr, "nmap(-r): wat? randomization is our raison d'etre!! rethink prease\n");
                exit(1);
            case 'n':
            case 'W':
            case '6':
                break;
            default:
                fprintf(stderr, "FAIL: unknown option: --%s\n", arg+1);
                fprintf(stderr, " [hint] try \"--help\"\n");
                fprintf(stderr, " [hint] ...or, to list nmap-compatible options, try \"--nmap\"\n");
                exit(1);
            }
            continue;
        }

        /* positional parameter: an IP address or range */
        if (!parse_range_string(&masscan->targets, &masscan->targets6, arg, 0, 0)) {
            fprintf(stderr, "FAIL: unknown command-line parameter \"%s\"\n", arg);
            fprintf(stderr, " [hint] did you want \"--%s\"?\n", arg);
            exit(1);
        }
        masscan->is_configured = 1;
    }

    /*
     * Print the warning about the seed, if needed
     */
    if ((masscan->shard_index != 1 || masscan->shard_total != 1) && !masscan->is_seed_set) {
        fprintf(stderr, "[-] WARNING: --seed <num> is not specified\n");
        fprintf(stderr, "    HINT: all shards must share the same seed\n");
    }

    /*
     * Read the default configuration file
     */
    masscan_read_config(masscan, "/etc/masscan/masscan.conf");

    /*
     * Initialize the packet capture library
     */
    pcap_init();

    /*
     * Handle the special commands
     */
    if (masscan->is_echo) {
        masscan_echo(masscan, stdout);
        return 0;
    }
    if (masscan->is_selftest) {
        return masscan_selftest();
    }
    if (masscan->is_iflist) {
        if (!pcap_is_loaded()) {
            fprintf(stderr, "libpcap not loaded\n");
            return 0;
        }
        return 0;
    }

    /*
     * Make sure we have something to scan
     */
    if (!masscan->is_configured) {
        masscan_usage();
        return 1;
    }
    if (masscan->targets.count == 0 && masscan->targets6.count == 0) {
        fprintf(stderr, "FAIL: target IP address list empty\n");
        fprintf(stderr, " [hint] try something like \"--range 10.0.0.0/8\"\n");
        fprintf(stderr, " [hint] try something like \"--range 192.168.0.100-192.168.0.200\"\n");
        return 1;
    }
    if (masscan->ports.count == 0) {
        fprintf(stderr, "FAIL: no ports were specified\n");
        fprintf(stderr, " [hint] try something like \"-p80,8000-9000\"\n");
        fprintf(stderr, " [hint] try something like \"--ports 0-65535\"\n");
        return 1;
    }

    /*
     * Start the scan
     */
    return masscan_scan(masscan);
}
