/***************************************************************************
 * Print a backtrace when the program crashes, mimicking the original.
 ***************************************************************************/
static void
crash_handler(int sig)
{
    void *addresses[24];
    int size;
    char **strings;
    int i;
    const char *progname = "masscan";

    {
        static char buf[512];
        ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf)-1);
        if (n > 0) {
            buf[n] = '\0';
            progname = strrchr(buf, '/');
            if (progname == NULL)
                progname = buf;
            else
                progname++;
        }
    }

    (void)sig;
    printf("======================================================================\n");
    printf(" Segmentation fault: please post this backtrace to:\n");
    printf(" https://github.com/robertdavidgraham/masscan/issues\n");
    printf("======================================================================\n");
    fflush(stdout);

    size = backtrace(addresses, 24);
    strings = backtrace_symbols(addresses, size);
    if (strings) {
        for (i=size-1; i>=0; i--) {
            printf("%d: [%s]\n", i+1, strings[i]);
        }
        free(strings);
    }
    fflush(stdout);
    _exit(1);
}

/***************************************************************************
 ***************************************************************************/
static void
install_crash_handler(void)
{
    signal(SIGSEGV, crash_handler);
    signal(SIGBUS, crash_handler);
    signal(SIGILL, crash_handler);
    signal(SIGABRT, crash_handler);
}

