/***************************************************************************
 * Read and process a configuration file.
 ***************************************************************************/
int
masscan_read_config(struct Masscan *masscan, const char *filename, int is_silent)
{
    FILE *fp;
    char line[65536];
    int exit_code = 0;

    errno = 0;
    fp = fopen(filename, "rb");
    if (fp == NULL) {
        int err = errno;
        char cwd[1024];
        if (is_silent)
            return 0;
        fprintf(stderr, "[-] FAIL: reading configuration file\\n");
        fprintf(stderr, "[-] %s: %s\\n", filename, strerror(err));
        if (getcwd(cwd, sizeof(cwd)))
            fprintf(stderr, "[-] cwd = %s\\n", cwd);
        else
            fprintf(stderr, "[-] cwd = \\n");
        return 0;
    }

    while (fgets(line, sizeof(line), fp)) {
        char *name, *value;
        char *p = line;
        size_t len;
        int idx = 1;

        /* trim trailing whitespace */
        len = strlen(line);
        while (len && (line[len-1] == '\\n' || line[len-1] == '\\r' ||
                       line[len-1] == ' ' || line[len-1] == '\\t'))
            line[--len] = '\\0';

        /* trim leading whitespace */
        while (*p == ' ' || *p == '\\t')
            p++;

        /* skip comments and empty lines */
        if (*p == '\\0' || *p == '#')
            continue;

        /* strip trailing comment */
        {
            char *h = strchr(p, '#');
            if (h)
                *h = '\\0';
            len = strlen(p);
            while (len && (p[len-1] == ' ' || p[len-1] == '\\t'))
                p[--len] = '\\0';
        }

        name = p;
        value = strchr(p, '=');
        if (value == NULL) {
            /* Lines without an equals sign are ignored */
            continue;
        }
        *value = '\\0';
        value++;
        /* trim the name */
        len = strlen(name);
        while (len && (name[len-1] == ' ' || name[len-1] == '\\t'))
            name[--len] = '\\0';
        while (*name == ' ' || *name == '\\t')
            name++;
        /* trim the value */
        while (*value == ' ' || *value == '\\t')
            value++;

        if (masscan_parse_parameter(masscan, name, value) == -1) {
            exit_code = 1;
            break;
        }
    }
    fclose(fp);
    return exit_code == 0;
}

