new = '''/***************************************************************************
 * IPv6 parser: returns the number of characters consumed, or 0 on failure.
 ***************************************************************************/
static unsigned
hexval(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return 0;
}

int
parse_ipv6(const char *value, ipv6_t *result)
{
    const char *p = value;
    unsigned left[8], right[8];
    unsigned nl = 0, nr = 0;
    int has_dbl = 0;
    ipv6_t addr = 0;
    unsigned i;
    const char *start = value;

    if (value == NULL || value[0] == '\\0')
        return 0;
    if (strchr(value, ':') == NULL)
        return 0;

    if (p[0] == ':') {
        if (p[1] != ':')
            return 0;
        has_dbl = 1;
        p += 2;
    }
    while (*p) {
        unsigned g = 0, digits = 0;
        while (isxdigit((unsigned char)*p)) {
            g = (g<<4) | hexval(*p);
            digits++;
            p++;
        }
        if (digits == 0 || digits > 4)
            return 0;
        if (*p == '.') {
            /* embedded IPv4 is not supported by masscan */
            return 0;
        }
        if (has_dbl) {
            if (nr >= 8)
                return 0;
            right[nr++] = g;
        } else {
            if (nl >= 8)
                return 0;
            left[nr=nr, nl++]= g;
        }
        if (*p == ':') {
            p++;
            if (*p == ':') {
                if (has_dbl)
                    return 0;
                has_dbl = 1;
                p++;
                if (*p == '\\0')
                    break;
                continue;
            } else if (*p == '\\0')
                return 0;
        } else if (*p == '\\0') {
            break;
        } else {
            return 0;
        }
    }
    if (!has_dbl) {
        if (nl != 8)
            return 0;
        for (i=0; i<8; i++)
            addr = (addr << 16) | left[i];
    } else {
        if (nl + nr > 8)
            return 0;
        for (i=0; i<nl; i++)
            addr = (addr << 16) | left[i];
        for (i=0; i < (8 - nl - nr); i++)
            addr = (addr << 16);
        for (i=0; i<nr; i++)
            addr = (addr << 16) | right[i];
    }
    *result = addr;
    return (int)(p - start);
}

'''
