new = '''/***************************************************************************
 * Parse a list of IP ranges.
 *   verbose: 0 = quiet, 1 = "bad IP address/range", 2 = "bad exclude address/range"
 ***************************************************************************/
static void
range_error(const char *value, int verbose, int is_dash)
{
    if (verbose == 0)
        return;
    if (is_dash)
        fprintf(stderr, "[-] _parser_next(): unknown coding failure\\n");
    if (verbose == 2)
        fprintf(stderr, "ERROR: bad exclude address/range: %s\\n", value);
    else
        fprintf(stderr, "ERROR: bad IP address/range: %s\\n", value);
}

int
parse_range_string(struct RangeList *list, struct RangeList6 *list6, const char *value,
                   int is_exclude, int verbose)
{
    const char *p = value;
    int result = 1;
    int is_dash = 0;

    if (value == NULL)
        return 1;
    if (value[0] == '-')
        is_dash = 1;

    for (;;) {
        uint32_t ip4 = 0, ip4b = 0;
        ipv6_t ip6 = 0, ip6b = 0;
        int is_v6 = 0;
        int n;

        while (*p == ' ' || *p == '\\t' || *p == ',' || *p == '\\r' || *p == '\\n')
            p++;
        if (*p == '\\0')
            break;
        if (isdigit((unsigned char)*p) && (n = parse_ipv4(p, &ip4)) != 0) {
            p += n;
        } else if ((n = parse_ipv6(p, &ip6)) != 0) {
            is_v6 = 1;
            p += n;
        } else {
            range_error(value, verbose, is_dash);
            result = 0;
            break;
        }

        /* Look for a prefix */
        if (*p == '/') {
            unsigned prefix = 0;
            int digits = 0;
            p++;
            while (isdigit((unsigned char)*p)) {
                prefix = prefix * 10 + (*p - '0');
                digits++;
                p++;
            }
            if (digits == 0)
                prefix = 0;
            if ((is_v6 && prefix > 128) || (!is_v6 && prefix > 32)) {
                range_error(value, verbose, is_dash);
                result = 0;
                break;
            }
            if (is_v6) {
                ipv6_t mask, base;
                if (prefix == 0)
                    base = 0;
                else
                    base = ip6 & ~(((ipv6_t)1<<(128-prefix)) - 1);
                mask = prefix == 0 ? 0 : (((ipv6_t)1<<(128-prefix)) - 1);
                rangelist_add6(list6, base, base | mask);
            } else {
                uint32_t mask, base;
                if (prefix == 0)
                    base = 0;
                else
                    base = ip4 & ~((uint32_t)((1ull<<(32-prefix)) - 1));
                mask = prefix == 0 ? 0xFFFFFFFFu : ((uint32_t)((1ull<<(32-prefix)) - 1));
                rangelist_add(list, base, base | mask);
            }
        } else if (*p == '-') {
            p++;
            if (is_v6) {
                if ((n = parse_ipv6(p, &ip6b)) == 0) {
                    range_error(value, verbose, is_dash);
                    result = 0;
                    break;
                }
                p += n;
                rangelist_add6(list6, ip6, ip6b);
            } else {
                if ((n = parse_ipv4(p, &ip4b)) == 0) {
                    range_error(value, verbose, is_dash);
                    result = 0;
                    break;
                }
                p += n;
                rangelist_add(list, ip4, ip4b);
            }
        } else {
            if (is_v6)
                rangelist_add6(list6, ip6, ip6);
            else
                rangelist_add(list, ip4, ip4);
        }

        /* Find the next separator */
        if (*p == '\\0')
            break;
        if (*p == ':')
            break;      /* ':' terminates the parse */
        if (*p == ',' || *p == ' ' || *p == '\\t' || *p == '\\r' || *p == '\\n')
            continue;
        range_error(value, verbose, is_dash);
        result = 0;
        break;
    }
    return result;
}

/***************************************************************************
 * Parse a port spec, like "80,8080-8090"
 ***************************************************************************/
int
parse_port_string(struct RangeList *list, const char *value)
{
    const char *p = value;
    int result = 1;

    if (value == NULL)
        return 1;

    for (;;) {
        unsigned port1 = 0, port2 = 0;
        int digits = 0;

        while (*p == ' ' || *p == '\\t' || *p == ',' || *p == '\\r' || *p == '\\n')
            p++;
        if (*p == '\\0')
            break;
        if (!isdigit((unsigned char)*p)) {
            break;
        }
        while (isdigit((unsigned char)*p)) {
            port1 = port1 * 10 + (*p - '0');
            digits++;
            p++;
        }
        port2 = port1;
        if (*p == '-') {
            p++;
            digits = 0;
            while (isdigit((unsigned char)*p)) {
                port2 = port2 * 10 + (*p - '0');
                digits++;
                p++;
            }
            if (digits == 0)
                port2 = port1;
        }
        if (port1 > 65535 || port2 > 65535) {
            fprintf(stderr, "[-] FAIL: bad target port: %s\\n", value);
            fprintf(stderr, "    Hint: a port is a number [0..65535]\\n");
            result = 0;
            break;
        }
        rangelist_add(list, port1, port2);
        if (*p == '\\0')
            break;
        if (*p == ':' || !(*p == ',' || *p == ' ' || *p == '\\t'))
            break;
    }
    return result;
}
